import fs from"fs";import{join}from"path";import{URL,fileURLToPath}from"url";import{minify}from"terser";const HELPERS_FOLDER=new URL("../src/helpers",import.meta.url),IGNORED_FILES=new Set(["package.json"]);export default async function generateHelpers(){let e="/*\n * This file is auto-generated! Do not modify it directly.\n * To re-generate run 'yarn gulp generate-runtime-helpers'\n */\n\nimport template from \"@babel/template\";\n\nfunction helper(minVersion: string, source: string) {\n  return Object.freeze({\n    minVersion,\n    ast: () => template.program.ast(source, { preserveComments: true }),\n  })\n}\n\nexport default Object.freeze({\n";for(const n of(await fs.promises.readdir(HELPERS_FOLDER)).sort()){if(IGNORED_FILES.has(n))continue;if(n.startsWith("."))continue;const[r]=n.split("."),t=join(fileURLToPath(HELPERS_FOLDER),n);if(!n.endsWith(".js")){console.error("ignoring",t);continue}const i=await fs.promises.readFile(t,"utf8"),s=i.match(/^\s*\/\*\s*@minVersion\s+(?<minVersion>\S+)\s*\*\/\s*$/m);if(!s)throw new Error(`@minVersion number missing in ${t}`);const{minVersion:o}=s.groups,m=await minify(i,{mangle:!1,compress:{directives:!1}});e+=`  ${JSON.stringify(r)}: helper(\n    ${JSON.stringify(o)},\n    ${JSON.stringify(m.code)},\n  ),\n`}return e+="});",e}